import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.CRfKVJQk.js";const u=JSON.parse('{"title":"FAQ","description":"Answers to common questions about React Native Liquid Glass: Expo Go, web support, the new architecture, performance, dark mode, FlatList and animation.","frontmatter":{"description":"Answers to common questions about React Native Liquid Glass: Expo Go, web support, the new architecture, performance, dark mode, FlatList and animation.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-glass-effect/reference/faq"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-glass-effect/reference/faq"}],["meta",{"property":"og:title","content":"FAQ · Liquid Glass for React Native"}],["meta",{"property":"og:description","content":"Answers to common questions about React Native Liquid Glass: Expo Go, web support, the new architecture, performance, dark mode, FlatList and animation."}],["meta",{"name":"twitter:title","content":"FAQ · Liquid Glass for React Native"}],["meta",{"name":"twitter:description","content":"Answers to common questions about React Native Liquid Glass: Expo Go, web support, the new architecture, performance, dark mode, FlatList and animation."}]]},"headers":[],"relativePath":"reference/faq.md","filePath":"reference/faq.md"}'),s={name:"reference/faq.md"};function r(n,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="does-it-work-in-expo-go" tabindex="-1">Does it work in Expo Go? <a class="header-anchor" href="#does-it-work-in-expo-go" aria-label="Permalink to &quot;Does it work in Expo Go?&quot;">​</a></h2><p>No real glass. Expo Go only runs native modules built into the Expo Go app. Components render a plain tinted view instead, so your layout still works. Use a dev build: <code>npx expo run:android</code>. See <a href="/react-native-glass-effect/installation/expo#expo-go">Expo</a>.</p><h2 id="do-i-need-a-config-plugin-for-expo" tabindex="-1">Do I need a config plugin for Expo? <a class="header-anchor" href="#do-i-need-a-config-plugin-for-expo" aria-label="Permalink to &quot;Do I need a config plugin for Expo?&quot;">​</a></h2><p>No. Autolinking picks the library up during <code>expo prebuild</code> and EAS builds.</p><h2 id="does-it-work-on-the-web" tabindex="-1">Does it work on the web? <a class="header-anchor" href="#does-it-work-on-the-web" aria-label="Permalink to &quot;Does it work on the web?&quot;">​</a></h2><p>Yes: React (Vite), Next.js (with server rendering) and Expo web. The glass uses CSS <code>backdrop-filter</code>, so blur, tint, border and corners work, but refraction and touch lighting don&#39;t. See <a href="/react-native-glass-effect/installation/web">Web</a>.</p><h2 id="does-it-work-with-the-old-architecture" tabindex="-1">Does it work with the old architecture? <a class="header-anchor" href="#does-it-work-with-the-old-architecture" aria-label="Permalink to &quot;Does it work with the old architecture?&quot;">​</a></h2><p>No. React Native&#39;s New Architecture (the default since 0.76) is required.</p><h2 id="why-do-i-need-glassbackdrop" tabindex="-1">Why do I need <code>GlassBackdrop</code>? <a class="header-anchor" href="#why-do-i-need-glassbackdrop" aria-label="Permalink to &quot;Why do I need `GlassBackdrop`?&quot;">​</a></h2><p>On Android a view can&#39;t see what&#39;s behind it, so the library needs to know what to blur. <code>GlassBackdrop</code> marks that content. On iOS and the web it&#39;s a plain view, so keeping it costs nothing and the same code works everywhere. See <a href="/react-native-glass-effect/guide/core-concepts">Core concepts</a>.</p><h2 id="why-does-ios-look-different-from-android" tabindex="-1">Why does iOS look different from Android? <a class="header-anchor" href="#why-does-ios-look-different-from-android" aria-label="Permalink to &quot;Why does iOS look different from Android?&quot;">​</a></h2><p>By default iOS uses Apple&#39;s own glass. For the same look on both, use <a href="/react-native-glass-effect/components/frosted-glass"><code>FrostedGlass</code></a> or <code>iosRenderer=&quot;shader&quot;</code>.</p><h2 id="is-it-expensive" tabindex="-1">Is it expensive? <a class="header-anchor" href="#is-it-expensive" aria-label="Permalink to &quot;Is it expensive?&quot;">​</a></h2><p>Glass costs GPU time while the content under it changes, roughly in proportion to the number of glass views, their size and the blur. A few headers, buttons and cards are fine on mid-range phones. The default <code>quality=&quot;auto&quot;</code> scales down on weak devices. See <a href="/react-native-glass-effect/features/quality">Quality and performance</a>.</p><h2 id="can-i-animate-glass" tabindex="-1">Can I animate glass? <a class="header-anchor" href="#can-i-animate-glass" aria-label="Permalink to &quot;Can I animate glass?&quot;">​</a></h2><p>Yes. Move, resize and transform glass views with <code>Animated</code> or Reanimated as usual. Changing glass props (material, tint, blur…) animates natively over <code>transitionDuration</code>. On iOS, avoid animating <code>opacity</code> on the glass itself.</p><h2 id="can-i-use-it-in-a-flatlist" tabindex="-1">Can I use it in a FlatList? <a class="header-anchor" href="#can-i-use-it-in-a-flatlist" aria-label="Permalink to &quot;Can I use it in a FlatList?&quot;">​</a></h2><p>Yes, as long as the backdrop is the background and not the list. See <a href="/react-native-glass-effect/recipes/cards-over-images">Cards over images</a>. Keep the number of glass items visible at once small.</p><h2 id="does-it-support-dark-mode" tabindex="-1">Does it support dark mode? <a class="header-anchor" href="#does-it-support-dark-mode" aria-label="Permalink to &quot;Does it support dark mode?&quot;">​</a></h2><p>Yes. Every material has light and dark values, and the library follows the system scheme. Force one with <code>colorScheme</code> in the theme.</p><h2 id="does-it-support-accessibility-settings" tabindex="-1">Does it support accessibility settings? <a class="header-anchor" href="#does-it-support-accessibility-settings" aria-label="Permalink to &quot;Does it support accessibility settings?&quot;">​</a></h2><p>Yes: Reduce Transparency (iOS), Reduce Motion, and screen readers. See <a href="/react-native-glass-effect/features/accessibility">Accessibility</a>.</p><h2 id="is-it-free-to-use" tabindex="-1">Is it free to use? <a class="header-anchor" href="#is-it-free-to-use" aria-label="Permalink to &quot;Is it free to use?&quot;">​</a></h2><p>Yes. It&#39;s MIT licensed.</p>',25)])])}const f=a(s,[["render",r]]);export{u as __pageData,f as default};
